import numpy as np
from scipy import stats

def _fit(X, y, it=30):
    n = len(y); A = np.column_stack([np.ones(n), X]) if X.size else np.ones((n, 1))
    b = np.zeros(A.shape[1])
    for _ in range(it):
        eta = np.clip(A @ b, -30, 30); p = 1 / (1 + np.exp(-eta)); w = p * (1 - p) + 1e-9
        H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
        step = np.linalg.solve(H, A.T @ (y - p)); b += step
        if np.max(np.abs(step)) < 1e-7: break
    p = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return np.sum(y * np.log(p) + (1 - y) * np.log(1 - p))

def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); ids = list(feats.ids)
    n, P = X.shape
    S = sorted(set(feats.stratum))
    Z = np.column_stack([[s == t for s in feats.stratum] for t in S[1:]]).astype(float) if len(S) > 1 else np.zeros((n, 0))
    R = np.corrcoef(X.T)
    def ll(cols, extra=None):
        M = [Z, X[:, cols]] + ([extra] if extra is not None else [])
        return _fit(np.column_stack(M), y)
    sel = []
    while len(sel) < MAX_DRIVERS:
        base = ll(sel); best, bj = None, None
        for j in range(P):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            pv = stats.chi2.sf(2 * (ll(sel + [j]) - base), 1)
            if best is None or pv < best: best, bj = pv, j
        alpha = (0.05 if not sel else 0.01) / P
        if bj is None or best > alpha: break
        sel.append(bj)
    changed = True
    while changed and sel:
        changed = False; full = ll(sel)
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - ll(rest)), 1) > 0.01 / P:
                sel.remove(j); changed = True; break
    prods = []; npair = P * (P + 1) // 2
    cand = []
    for a in range(P):
        for b in range(a, P):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b}); base = ll(mains)
            pv = stats.chi2.sf(2 * (ll(mains, X[:, a] * X[:, b]) - base), 1)
            if pv < 0.01 / npair: cand.append((pv, a, b))
    cand.sort()
    for pv, a, b in cand[:2]:
        prods.append((ids[a], ids[b]))
    drivers = [ids[j] for j in sel]
    for _, a, b in cand[:2]:
        for j in (a, b):
            if ids[j] not in drivers and len(drivers) < MAX_DRIVERS: drivers.append(ids[j])
    cols = sorted(set(sel) | {j for _, a, b in cand[:2] for j in (a, b)})
    return Design(drivers=tuple(drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple(prods), loadings={})

